fun gridColumnCount(
    contentWidthDp: Float,
    maxCardWidthDp: Float,
    spacingDp: Float = CardGridSpec.GridSpacing.value,
): Int {
    val step = maxCardWidthDp + spacingDp
    if (!contentWidthDp.isFinite() || !step.isFinite() || step <= 0f) return 1
    return max(1, ceil((contentWidthDp - spacingDp) / step).toInt())
}

